import fs from "node:fs";
import path from "node:path";

const artifactPath = path.join(process.cwd(), "nft", "out", "TailsAndTrailsArchive.sol", "TailsAndTrailsArchive.json");
const outputPath = path.join(process.cwd(), "mint-app", "src", "generatedContract.ts");
const artifact = JSON.parse(fs.readFileSync(artifactPath, "utf8"));
const bytecode = artifact.bytecode?.object;
if (!bytecode?.startsWith("0x")) throw new Error("Compiled contract bytecode is unavailable");

const source = [
  "// Generated by scripts/export-mint-contract.mjs from the tested Foundry artifact.",
  `export const archiveCreationBytecode = ${JSON.stringify(bytecode)} as \`0x${"${string}"}\`;`,
  "",
].join("\n");
fs.writeFileSync(outputPath, source);
console.log(JSON.stringify({ outputPath, bytes: (bytecode.length - 2) / 2 }));
